+export function detentionCents(stop: StopEvent): number {
+  if (!stop.arrivedAt || !stop.departedAt) return 0;
+  const minutesOnSite = (stop.departedAt.getTime() - stop.arrivedAt.getTime()) / 60_000;
+  const billableHours = Math.floor((minutesOnSite - FREE_MINUTES) / 60);
+  return Math.max(0, billableHours) * HOURLY_RATE_CENTS;
